   <AppSkeleton v-if="loading" variant="cards" label="جارٍ تحميل الطلبات…"/>
   <section v-else-if="error" class="my-orders-empty my-orders-error" role="alert"><h3>تعذر تحميل طلباتك</h3><p>{{ error.message }}</p><p v-for="(messages,key) in error.errors" :key="key">{{ messages.join(' ') }}</p><button type="button" class="button" @click="load()">إعادة المحاولة</button></section>
   <template v-else-if="data"><section v-if="!data.data.length" class="my-orders-empty"><span class="orders-empty-icon"><SiteIcon name="shopping-bag"/></span><h3>لا توجد طلبات بعد</h3><p>اختر وجبتك المفضلة من المنيو، وستجد طلبك هنا بعد تأكيده.</p><RouterLink class="button button-primary" to="/menu">تصفح المنيو</RouterLink></section>
    <div v-else class="customer-orders"><article v-for="order in data.data" :key="order.id" class="customer-order-card" :class="{'is-current':!isTerminalOrder(order.status),'is-cancelled':order.status==='cancelled'}"><div class="customer-order-heading"><div><span class="customer-order-caption">رقم الطلب</span><h3 class="order-number" dir="ltr">{{ order.order_number }}</h3></div><div class="customer-order-status"><span>حالة الطلب</span><OrderStatusBadge :status="order.status"/></div></div><div class="customer-order-meta"><span><SiteIcon :name="order.type==='delivery'?'truck':'shopping-bag'"/> {{ getOrderTypeLabel(order.type) }}</span><span v-if="order.branch?.name"><SiteIcon name="map-pin"/> {{ order.branch.name }}</span></div><p class="customer-order-date"><SiteIcon name="clock"/> {{ formatDateTime(order.placed_at) }}</p><p v-if="order.items?.length" class="customer-order-items">{{ order.items.slice(0,2).map(item=>item.quantity+' × '+item.product.name).join('، ') }}<span v-if="order.items.length>2">، وأصناف أخرى</span></p><div class="customer-order-total"><div><span>إجمالي الطلب</span><strong>{{ formatCurrency(order.pricing.total) }}</strong></div><div class="customer-order-payment"><span>{{ getPaymentMethodLabel(order.payment.method) }}</span><strong :class="{'is-paid':order.payment.status==='paid'}">{{ getPaymentStatusLabel(order.payment.status) }}</strong></div></div><div class="customer-order-actions"><RouterLink v-if="!isTerminalOrder(order.status)" class="button button-primary" :to="{name:'track-order.detail',params:{orderUuid:order.id}}">تتبع الطلب <SiteIcon name="arrow-left"/></RouterLink><RouterLink :class="isTerminalOrder(order.status)?'button order-details-button':'order-details-link'" :to="{name:'account.order',params:{orderUuid:order.id}}">تفاصيل الطلب <SiteIcon v-if="isTerminalOrder(order.status)" name="arrow-left"/></RouterLink></div></article></div>
    <ApiPagination :meta="data.meta" :links="data.links" :busy="loading" @page="load"/>
   </template>
  </template>
  <SavedGuestOrders :signed-in="auth.isAuthenticated" enhanced/>
 </main>
